body {
  margin: 0;
  display: flex;
  flex-direction: column;
  min-height: 100vh;
}

.container {
  max-width: 800px;
  margin: 0 auto;
  padding: 2rem;
  flex: 1;
}

h1 {
  font-size: 2.5rem;
  line-height: 1.1;
  margin-bottom: 2rem;
}

#message-list {
  flex: 1;
  overflow-y: auto;
  margin-bottom: 2rem;
  border-bottom: 1px solid #444;
  padding-bottom: 1rem;
}

.message-item {
  background-color: #333;
  padding: 1rem;
  border-radius: 8px;
  margin-bottom: 1rem;
}

.message-text {
  font-size: 1.1rem;
  margin-bottom: 0.5rem;
  word-wrap: break-word;
}

.message-meta {
  font-size: 0.85rem;
  color: #aaa;
}

#message-form {
  display: flex;
  gap: 0.5rem;
}

#message-input {
  flex: 1;
  padding: 0.75rem;
  border: none;
  border-radius: 4px;
  font-size: 1rem;
  background-color: #333;
  color: #fff;
}

button {
  padding: 0.75rem 1.5rem;
  border: none;
  border-radius: 4px;
  font-size: 1rem;
  font-weight: 500;
  cursor: pointer;
  background-color: #646cff;
  color: #fff;
  transition: background-color 0.25s;
}

button:hover {
  background-color: #747bff;
}

button:focus,
#message-input:focus {
  outline: 4px auto -webkit-focus-ring-color;
}

@media (prefers-color-scheme: light) {
  :root {
    color: #213547;
    background-color: #ffffff;
  }

  .message-item {
    background-color: #f5f5f5;
  }

  #message-input {
    background-color: #f5f5f5;
    color: #333;
  }
}

